/** Execute only commands backed by an explicitly registered canonical adapter.
 * Evidence submitted by the browser is never used as proof of command success. */
export async function executeMarketLaunchStageCommand(env,actor,packageVersionId,taskKey,stepKey,requestId='',input={}){
 const workbench=await getMarketLaunchWorkbench(env,packageVersionId);
 const task=workbench.tasks.find(x=>x.key===taskKey);
 if(!task)throw fail('Unknown market launch task.',404,'MARKET_LAUNCH_TASK_NOT_FOUND');
 const contract=await getMarketLaunchStageContract(env,packageVersionId,taskKey);
 const step=contract.steps.find(x=>x.key===stepKey);
 if(!step)throw fail('Unknown stage-contract step.',404,'MARKET_LAUNCH_STEP_NOT_FOUND');
 const adapter=MARKET_LAUNCH_COMMAND_ADAPTERS[step.permittedCommand];
 if(!adapter)throw fail(`No registered owning-authority adapter exists for ${step.permittedCommand}. Submit evidence only; this step remains unverified until its owning adapter is implemented.`,409,'MARKET_LAUNCH_COMMAND_ADAPTER_UNAVAILABLE');
 if(step.status==='COMPLETE'&&step.authorityVerified===true)return contract;
 for(const prerequisite of step.prerequisites||[]){const prior=contract.steps.find(x=>x.key===prerequisite);if(prior&&!(prior.status==='COMPLETE'&&prior.authorityVerified===true))throw fail(`Command blocked: prerequisite ${prerequisite} has no verified canonical outcome.`,409,'MARKET_LAUNCH_STEP_PREREQUISITE_BLOCKED');}
 const outcome=await adapter(env,Number(packageVersionId),taskKey,actor,requestId,obj(input));
 if((step.permittedCommand==='canonical.validate'&&outcome.result.safeToApply!==true)||(step.permittedCommand==='certification.testlab.run'&&outcome.result.ready!==true)){
  const blockedCode=step.permittedCommand==='canonical.validate'?'MARKET_LAUNCH_CANONICAL_VALIDATION_BLOCKED':'MARKET_LAUNCH_TESTLAB_BLOCKED';
  const row=await env.DB.prepare('SELECT evidence_json FROM platform_market_launch_task_evidence WHERE package_version_id=? AND task_key=? LIMIT 1').bind(Number(packageVersionId),taskKey).first();
  const evidence=parseJson(row?.evidence_json||'{}');const prior=evidence.stageContract&&evidence.stageContract.contractKey===contract.contractKey?evidence.stageContract:contract;
  evidence.stageContract={...prior,steps:contract.steps.map(x=>x.key===stepKey?{...x,status:'BLOCKED',authorityVerified:false,commandOutcome:outcome.result}:x),updatedAt:new Date().toISOString()};
  await env.DB.prepare(`INSERT INTO platform_market_launch_task_evidence(package_version_id,task_key,status,evidence_json,updated_by_type,updated_by_id,updated_at) VALUES(?,?,?,?,?,?,CURRENT_TIMESTAMP) ON CONFLICT(package_version_id,task_key) DO UPDATE SET status='IN_PROGRESS',evidence_json=excluded.evidence_json,updated_by_type=excluded.updated_by_type,updated_by_id=excluded.updated_by_id,updated_at=CURRENT_TIMESTAMP`).bind(Number(packageVersionId),taskKey,'IN_PROGRESS',JSON.stringify({...evidence,recordedAt:new Date().toISOString()}),actor.role,actor.id||null).run();
  await auditAdminControl(env,{actor,action:'admin.market-factory.launch-command.blocked',resourceType:'market_package_version',resourceId:packageVersionId,requestId,metadata:{taskKey,stepKey,adapter:outcome.adapter,conflicts:outcome.result.conflicts?.length||0}}).catch(error=>{throw authorityUnavailable('market_factory_audit',error);});
  throw fail(step.permittedCommand==='canonical.validate'?`Canonical validation found ${outcome.result.conflicts?.length||0} conflict(s); step remains blocked.`:`Canonical Product Test Lab has ${outcome.result.summary?.blocked||'unknown'} blocker(s); step remains blocked.`,409,blockedCode);
 }
 const row=await env.DB.prepare('SELECT evidence_json FROM platform_market_launch_task_evidence WHERE package_version_id=? AND task_key=? LIMIT 1').bind(Number(packageVersionId),taskKey).first();
 const evidence=parseJson(row?.evidence_json||'{}');const prior=evidence.stageContract&&evidence.stageContract.contractKey===contract.contractKey?evidence.stageContract:contract;
 const canonicalEvidence={summary:`Canonical command ${outcome.adapter} completed and returned a server-generated result.`,evidenceRef:`market-launch:${packageVersionId}:${taskKey}:${stepKey}:${outcome.adapter}`,submittedAt:new Date().toISOString(),submittedBy:actor.id||actor.role,authorityResult:outcome.result,authority:outcome.adapter};
 evidence.stageContract={...prior,steps:contract.steps.map(x=>x.key===stepKey?{...x,status:'COMPLETE',authorityVerified:true,verifiedAt:new Date().toISOString(),verifiedBy:actor.id||actor.role,evidence:canonicalEvidence,commandOutcome:outcome.result}:x),updatedAt:new Date().toISOString()};
 await env.DB.prepare(`INSERT INTO platform_market_launch_task_evidence(package_version_id,task_key,status,evidence_json,updated_by_type,updated_by_id,updated_at) VALUES(?,?,?,?,?,?,CURRENT_TIMESTAMP) ON CONFLICT(package_version_id,task_key) DO UPDATE SET evidence_json=excluded.evidence_json,updated_by_type=excluded.updated_by_type,updated_by_id=excluded.updated_by_id,updated_at=CURRENT_TIMESTAMP`).bind(Number(packageVersionId),taskKey,task.status==='TODO'?'IN_PROGRESS':task.status,JSON.stringify({...evidence,recordedAt:new Date().toISOString()}),actor.role,actor.id||null).run();
 await auditAdminControl(env,{actor,action:'admin.market-factory.launch-command.executed',resourceType:'market_package_version',resourceId:packageVersionId,requestId,metadata:{taskKey,stepKey,adapter:outcome.adapter,permittedCommand:step.permittedCommand}}).catch(error=>{throw authorityUnavailable('market_factory_audit',error);});
 return getMarketLaunchStageContract(env,packageVersionId,taskKey);
}

export async function updateMarketLaunchTask(env,actor,packageVersionId,taskKey,input={},requestId=''){
 const wb=await getMarketLaunchWorkbench(env,packageVersionId);const task=wb.tasks.find(x=>x.key===taskKey);if(!task)throw fail('Unknown market launch task.',404,'MARKET_LAUNCH_TASK_NOT_FOUND');const status=String(input.status||'IN_PROGRESS').toUpperCase();if(!['TODO','IN_PROGRESS','BLOCKED','COMPLETE'].includes(status))throw fail('Invalid task status.',422,'MARKET_LAUNCH_TASK_STATUS_INVALID');const evidence=obj(input.evidence);if(status==='COMPLETE'){const persistedRow=await env.DB.prepare('SELECT evidence_json FROM platform_market_launch_task_evidence WHERE package_version_id=? AND task_key=? LIMIT 1').bind(Number(packageVersionId),taskKey).first();const persistedEvidence=parseJson(persistedRow?.evidence_json||'{}');const persistedContract=persistedEvidence.stageContract;if(persistedContract&&Array.isArray(persistedContract.steps)){const incomplete=persistedContract.steps.filter(x=>x.required!==false&&x.status!=='COMPLETE');if(incomplete.length)throw fail(`Task cannot be completed: ${incomplete.length} required persisted contract substep(s) remain incomplete.`,409,'MARKET_LAUNCH_STAGE_CONTRACT_INCOMPLETE');}else{if(evidence.stageContract&&Array.isArray(evidence.stageContract.steps))throw fail('Browser-supplied contract state is not authoritative. Load and complete the server-owned stage contract first.',409,'MARKET_LAUNCH_STAGE_CONTRACT_NOT_PERSISTED');const initialContract=buildMarketLaunchStageContract(task,packageVersionId);throw fail(`Task cannot be completed before its canonical stage contract is initialized and verified: ${initialContract.steps.length} required substep(s) remain.`,409,'MARKET_LAUNCH_STAGE_CONTRACT_NOT_PERSISTED');}requireMarketLaunchEvidence(evidence);if(task.key.startsWith('legal:')&&(!clean(evidence.reviewer,180)||!clean(evidence.decision,80)))throw fail('Legal review evidence requires reviewer and decision.',422,'MARKET_LAUNCH_LEGAL_EVIDENCE_REQUIRED');const v=await env.DB.prepare(`SELECT package_json,market_status FROM (SELECT v.package_json,p.status market_status FROM platform_market_package_versions v JOIN platform_market_packages p ON p.id=v.package_id WHERE v.id=?)`).bind(Number(packageVersionId)).first();const pkg=parseJson(v?.package_json||'{}');let prerequisite='';if(task.key==='market-status'&&['RETIRED','SUSPENDED'].includes(v?.market_status))prerequisite=`Market status is ${v.market_status}; resolve the lifecycle state first.`;if(task.key.startsWith('legal:')){const item=pkg.legal?.find(x=>x.key===task.key.slice(6));if(item?.status!=='reviewed')prerequisite='Update this package in a new immutable version after the legal review; status must be reviewed.';}if(task.key.startsWith('content:')){const item=pkg.content?.find(x=>x.code===task.key.slice(8));if(!String(item?.body||'').trim()||!['validated','active'].includes(String(item?.status||'').toLowerCase())||/must be (completed|added|reviewed)|placeholder|lorem ipsum/i.test(item?.body||''))prerequisite='Update and validate this content in a new immutable package version first.';}if(task.key==='reconciliation'&&!wb.preview.safeToApply)prerequisite='Resolve reconciliation conflicts first.';if(prerequisite)throw fail(`Task cannot be completed: ${prerequisite}`,409,'MARKET_LAUNCH_TASK_GATE_BLOCKED');}
 const versionRow=await env.DB.prepare(`SELECT status FROM platform_market_package_versions WHERE id=? LIMIT 1`).bind(Number(packageVersionId)).first();if(!versionRow)throw fail('Market package version not found.',404,'MARKET_PACKAGE_VERSION_NOT_FOUND');if(['AUTHORIZED','PUBLISHED','VERIFIED','LIVE','REPLACED','SUSPENDED','RETIRED'].includes(String(versionRow.status).toUpperCase())&&task.key!=='release-report')throw fail('This release is already authorized or beyond; create a new immutable version for pre-publication evidence changes.',409,'MARKET_LAUNCH_VERSION_IMMUTABLE');const serialized=JSON.stringify({...evidence,recordedAt:new Date().toISOString()});await env.DB.prepare(`INSERT INTO platform_market_launch_task_evidence(package_version_id,task_key,status,evidence_json,updated_by_type,updated_by_id,updated_at) VALUES(?,?,?,?,?,?,CURRENT_TIMESTAMP) ON CONFLICT(package_version_id,task_key) DO UPDATE SET status=excluded.status,evidence_json=excluded.evidence_json,updated_by_type=excluded.updated_by_type,updated_by_id=excluded.updated_by_id,updated_at=CURRENT_TIMESTAMP`).bind(Number(packageVersionId),taskKey,status,serialized,actor.role,actor.id||null).run();if(String(versionRow.status).toUpperCase()==='VALIDATED'&&task.key!=='release-report')await env.DB.prepare(`UPDATE platform_market_package_versions SET status='DRAFT',readiness_json='{}',dependency_snapshot_json='{}',updated_at=CURRENT_TIMESTAMP WHERE id=? AND status='VALIDATED'`).bind(Number(packageVersionId)).run();await auditAdminControl(env,{actor,action:'admin.market-factory.launch-task.updated',resourceType:'market_package_version',resourceId:packageVersionId,requestId,metadata:{taskKey,status,evidenceRef:clean(evidence.evidenceRef,1000)}}).catch(error=>{throw authorityUnavailable('market_factory_audit',error);});return getMarketLaunchWorkbench(env,packageVersionId);
}

async function reconcileRuntimeGovernance(env,pkg){
 const g=pkg.governance||{};const evidence={jurisdiction:null,sectorPolicies:[],residency:null,retention:[],billing:[],notifications:[]};
 if(g.jurisdiction?.code){const x=g.jurisdiction;await env.DB.prepare(`INSERT INTO jurisdiction_policies(code,country_code,region_code,framework_code,data_residency_mode,retention_profile,deletion_profile,identity_profile,audit_profile,effective_version,status,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,CURRENT_TIMESTAMP) ON CONFLICT(code) DO UPDATE SET country_code=excluded.country_code,region_code=excluded.region_code,framework_code=excluded.framework_code,data_residency_mode=excluded.data_residency_mode,retention_profile=excluded.retention_profile,deletion_profile=excluded.deletion_profile,identity_profile=excluded.identity_profile,audit_profile=excluded.audit_profile,effective_version=excluded.effective_version,status=excluded.status,updated_at=CURRENT_TIMESTAMP`).bind(key(x.code),pkg.country.iso,clean(x.regionCode,80)||null,clean(x.frameworkCode,120)||'market',clean(x.dataResidencyMode,40)||'policy',clean(x.retentionProfile,80)||'default',clean(x.deletionProfile,80)||'default',clean(x.identityProfile,80)||'default',clean(x.auditProfile,80)||'default',clean(x.effectiveVersion,40)||pkg.metadata.version,clean(x.status,30)||'active').run();evidence.jurisdiction=x.code;}
 for(const x of arr(g.sectorPolicies)){if(!x.code||!x.sectorCode)throw fail('Each governance.sectorPolicies entry requires code and sectorCode.',422,'MARKET_GOVERNANCE_INVALID');await env.DB.prepare(`INSERT INTO sector_policies(code,sector_code,regulatory_profile,data_profile,effective_version,status,updated_at) VALUES(?,?,?,?,?, ?,CURRENT_TIMESTAMP) ON CONFLICT(code) DO UPDATE SET sector_code=excluded.sector_code,regulatory_profile=excluded.regulatory_profile,data_profile=excluded.data_profile,effective_version=excluded.effective_version,status=excluded.status,updated_at=CURRENT_TIMESTAMP`).bind(key(x.code),key(x.sectorCode),clean(x.regulatoryProfile,160)||'general_operational',clean(x.dataProfile,120)||'standard',clean(x.effectiveVersion,40)||pkg.metadata.version,clean(x.status,30)||'active').run();evidence.sectorPolicies.push(x.code);}
 if(g.residency?.code){const x=g.residency;await env.DB.prepare(`INSERT INTO residency_policies(code,jurisdiction_code,primary_region,primary_provider,mode,fallback_allowed,version,active) VALUES(?,?,?,?,?,?,?,1) ON CONFLICT(code) DO UPDATE SET jurisdiction_code=excluded.jurisdiction_code,primary_region=excluded.primary_region,primary_provider=excluded.primary_provider,mode=excluded.mode,fallback_allowed=excluded.fallback_allowed,version=excluded.version,active=1`).bind(key(x.code),clean(x.jurisdictionCode,120)||g.jurisdiction?.code||`${pkg.country.iso}-JURISDICTION`,clean(x.primaryRegion,120),clean(x.primaryProvider,120),['required','preferred','policy'].includes(x.mode)?x.mode:'policy',x.fallbackAllowed?1:0,clean(x.version,40)||pkg.metadata.version).run();evidence.residency=x.code;}
 for(const x of arr(g.retention)){if(!x.code||!x.purposeCode)throw fail('Each governance.retention entry requires code and purposeCode.',422,'MARKET_GOVERNANCE_INVALID');await env.DB.prepare(`INSERT INTO retention_policies(code,purpose_code,jurisdiction_code,sector_code,retention_days,action_after_expiry,legal_hold_allowed,version,active) VALUES(?,?,?,?,?,?,?,?,1) ON CONFLICT(code) DO UPDATE SET purpose_code=excluded.purpose_code,jurisdiction_code=excluded.jurisdiction_code,sector_code=excluded.sector_code,retention_days=excluded.retention_days,action_after_expiry=excluded.action_after_expiry,legal_hold_allowed=excluded.legal_hold_allowed,version=excluded.version,active=1`).bind(key(x.code),key(x.purposeCode),clean(x.jurisdictionCode,120)||g.jurisdiction?.code||`${pkg.country.iso}-JURISDICTION`,key(x.sectorCode||'general'),Number.isInteger(Number(x.retentionDays))?Number(x.retentionDays):null,['delete','anonymize','restrict','review'].includes(x.actionAfterExpiry)?x.actionAfterExpiry:'review',x.legalHoldAllowed===false?0:1,clean(x.version,40)||pkg.metadata.version).run();evidence.retention.push(x.code);}
 for(const x of arr(g.billing)){if(!x.jurisdictionCode||!x.currency)throw fail('Each governance.billing entry requires jurisdictionCode and currency.',422,'MARKET_GOVERNANCE_INVALID');const version=clean(x.version,40)||pkg.metadata.version;const existing=await env.DB.prepare(`SELECT id FROM billing_jurisdiction_policies WHERE country_code=? AND jurisdiction_code=? AND version=? LIMIT 1`).bind(pkg.country.iso,clean(x.jurisdictionCode,120),version).first();if(existing)await env.DB.prepare(`UPDATE billing_jurisdiction_policies SET currency=?,tax_configuration_code=?,invoice_requirements_json=?,provider_code=?,status=?,active=1,updated_at=CURRENT_TIMESTAMP WHERE id=?`).bind(clean(x.currency,3).toUpperCase(),clean(x.taxConfigurationCode,120),JSON.stringify(obj(x.invoiceRequirements)),clean(x.providerCode,120)||null,clean(x.status,30)||'active',Number(existing.id)).run();else await env.DB.prepare(`INSERT INTO billing_jurisdiction_policies(country_code,jurisdiction_code,currency,tax_configuration_code,invoice_requirements_json,provider_code,status,version,active) VALUES(?,?,?,?,?,?,?,?,1)`).bind(pkg.country.iso,clean(x.jurisdictionCode,120),clean(x.currency,3).toUpperCase(),clean(x.taxConfigurationCode,120),JSON.stringify(obj(x.invoiceRequirements)),clean(x.providerCode,120)||null,clean(x.status,30)||'active',version).run();evidence.billing.push(`${x.jurisdictionCode}:${version}`);}
 for(const x of arr(g.notifications)){if(!x.notificationType||!x.purposeCode)throw fail('Each governance.notifications entry requires notificationType and purposeCode.',422,'MARKET_GOVERNANCE_INVALID');const existing=await env.DB.prepare(`SELECT id FROM notification_policy_registry WHERE notification_type=? AND company_id IS NULL AND country_code=? AND version=? ORDER BY id DESC LIMIT 1`).bind(clean(x.notificationType,120),pkg.country.iso,clean(x.version,40)||pkg.metadata.version).first();const values=[clean(x.notificationType,120),pkg.country.iso,key(x.purposeCode),clean(x.classification,40)||'INTERNAL',clean(x.providerCode,120)||'in_app',clean(x.retentionPolicyCode,120)||null,JSON.stringify(arr(x.allowedRecipientRoles||['admin','driver','executor'])),Number(x.maxTitleLength||160),Number(x.maxBodyLength||600),x.minimize===false?0:1,x.auditRequired===false?0:1,clean(x.version,40)||pkg.metadata.version];if(existing)await env.DB.prepare(`UPDATE notification_policy_registry SET purpose_code=?,classification=?,provider_code=?,retention_policy_code=?,allowed_recipient_roles=?,max_title_length=?,max_body_length=?,minimize=?,audit_required=?,active=1,updated_at=CURRENT_TIMESTAMP WHERE id=?`).bind(...values.slice(2),Number(existing.id)).run();else await env.DB.prepare(`INSERT INTO notification_policy_registry(notification_type,company_id,country_code,purpose_code,classification,provider_code,retention_policy_code,allowed_recipient_roles,max_title_length,max_body_length,minimize,audit_required,version,active) VALUES(?,NULL,?,?,?,?,?,?,?,?,?,?,?,1)`).bind(...values).run();evidence.notifications.push(x.notificationType);}
 return evidence;
}

async function stageComposition(env,pkg,actor){
 const canonical=await inspectCanonicalTargets(env,pkg);
 // The composition is created only against canonical product identities. No live canonical
 // country/sector/policy/content record is changed until publication.
 const bp=await env.DB.prepare(`SELECT id FROM platform_country_product_blueprints WHERE country_code=? LIMIT 1`).bind(pkg.country.iso).first();
 if(!bp)return {canonical,launch:null,definitions:[],blockers:[]};
 const launch=await env.DB.prepare(`SELECT id,status,version,active FROM country_product_launches WHERE country_code=? AND status='draft' AND active=0 ORDER BY id DESC LIMIT 1`).bind(pkg.country.iso).first();
 return {canonical,launch,definitions:launch?(await env.DB.prepare(`SELECT id,sector_code,definition_version,status,compiled_hash FROM platform_product_definitions WHERE launch_id=?`).bind(Number(launch.id)).all()).results||[]:[],blockers:[]};
}

export async function validateMarketPackage(env,actor,packageVersionId,requestId=''){
 const v=await env.DB.prepare(`SELECT * FROM platform_market_package_versions WHERE id=? LIMIT 1`).bind(Number(packageVersionId)).first();if(!v)throw fail('Market package version not found',404,'MARKET_PACKAGE_VERSION_NOT_FOUND');
 const pkg=parseJson(v.package_json);const market=await env.DB.prepare(`SELECT * FROM platform_market_packages WHERE id=?`).bind(Number(v.package_id)).first();
 const canonical=await inspectCanonicalTargets(env,pkg);const blockers=[];const warnings=[];const placement=pkg.regionalPlacement||{};if(pkg.country.iso==='DE'||placement.regionKey){if(!placement.regionKey||!placement.jurisdictionCode)blockers.push({code:'REGIONAL_PLACEMENT_CONTRACT_REQUIRED',message:'A regional placement key and jurisdiction are required before this market can be published.'});else{const placementRow=await env.DB.prepare('SELECT region_key,jurisdiction_code,status,activation_allowed,policy_version FROM platform_region_placements WHERE region_key=? LIMIT 1').bind(placement.regionKey).first();if(!placementRow)blockers.push({code:'REGIONAL_PLACEMENT_NOT_REGISTERED',message:`Regional placement ${placement.regionKey} is not registered.`});else if(String(placementRow.jurisdiction_code)!==String(placement.jurisdictionCode))blockers.push({code:'REGIONAL_PLACEMENT_JURISDICTION_MISMATCH',message:'Market package jurisdiction does not match the canonical placement registry.'});else if(placementRow.status!=='ACTIVE'||Number(placementRow.activation_allowed)!==1)blockers.push({code:'REGIONAL_PLACEMENT_NOT_ACTIVE',message:`Regional placement ${placement.regionKey} is ${placementRow.status}; market publication remains blocked until the region passes its independent activation gates.`});if(placement.policyVersion&&placementRow&&String(placement.policyVersion)!==String(placementRow.policy_version))blockers.push({code:'REGIONAL_PLACEMENT_POLICY_VERSION_MISMATCH',message:'Market package placement policy version differs from the registry.'});}}const reconciliation=await previewMarketReconciliation(env,Number(v.id));for(const conflict of reconciliation.conflicts)blockers.push({code:conflict.code,message:conflict.message});if(['RETIRED','SUSPENDED','RESTRICTED'].includes(String(market?.status||'').toUpperCase()))blockers.push({code:'MARKET_STATUS_BLOCKS_PUBLICATION',message:`Market status ${market.status} must be explicitly resolved before publication.`});
 if(!canonical.country)warnings.push({code:'COUNTRY_WILL_BE_CREATED',message:`Product market country ${pkg.country.iso} will be created/reconciled at publication.`});
 for(const x of canonical.sectors.filter(x=>!x.exists))warnings.push({code:'SECTOR_WILL_BE_CREATED',message:`Canonical sector ${x.code} will be created/reconciled at publication.`});
 for(const x of canonical.policies.filter(x=>!x.exists))warnings.push({code:'POLICY_WILL_BE_CREATED',message:`Canonical policy ${x.code} will be created/reconciled at publication.`});
 for(const x of canonical.content.filter(x=>!x.exists))warnings.push({code:'CONTENT_WILL_BE_CREATED',message:`Canonical content ${x.code} will be created/reconciled at publication.`});
 const dependencies=await dependencySnapshotForPackage(env,pkg);blockers.push(...dependencies.missing.map(x=>({code:'DEPENDENCY_'+x.type.toUpperCase()+'_'+x.code.toUpperCase(),message:`Missing or inactive canonical ${x.type}: ${x.code}`})));
 if(!pkg.policies.length)blockers.push({code:'POLICIES_REQUIRED',message:'At least one market policy is required.'});if(!pkg.governance?.jurisdiction)blockers.push({code:'JURISDICTION_PACKAGE_REQUIRED',message:'Governance jurisdiction policy is required for a publishable market package.'});if(!arr(pkg.governance?.sectorPolicies).length)blockers.push({code:'SECTOR_POLICY_PACKAGE_REQUIRED',message:'At least one sector policy is required.'});if(!pkg.governance?.residency)blockers.push({code:'RESIDENCY_PACKAGE_REQUIRED',message:'Residency policy is required.'});if(arr(pkg.governance?.retention).length<5)blockers.push({code:'RETENTION_PACKAGE_INCOMPLETE',message:'At least five governed retention purposes are required.'});if(!pkg.content.length)blockers.push({code:'CONTENT_REQUIRED',message:'At least one market content entry is required.'});if(!pkg.languages.length)blockers.push({code:'LANGUAGES_REQUIRED',message:'At least one language is required.'});if(!pkg.sectors.length)blockers.push({code:'SECTORS_REQUIRED',message:'At least one sector is required.'});for(const item of pkg.legal.filter(x=>x.required&&x.status!=='reviewed'))blockers.push({code:'LEGAL_REVIEW_REQUIRED_'+item.key.toUpperCase().replace(/[^A-Z0-9]+/g,'_'),message:`Required legal item ${item.title} must be reviewed before market publication.`});for(const item of pkg.content){if(!String(item.body||'').trim())blockers.push({code:'CONTENT_BODY_REQUIRED_'+item.code.toUpperCase().replace(/[^A-Z0-9]+/g,'_'),message:`Content ${item.code} has no body.`});if(/must be (completed|added|reviewed)|placeholder|lorem ipsum/i.test(String(item.body||'')))blockers.push({code:'CONTENT_PLACEHOLDER_'+item.code.toUpperCase().replace(/[^A-Z0-9]+/g,'_'),message:`Content ${item.code} still appears to contain placeholder instructions and is not customer-ready.`});if(!['validated','active'].includes(String(item.status||'draft').toLowerCase()))blockers.push({code:'CONTENT_REVIEW_REQUIRED_'+item.code.toUpperCase().replace(/[^A-Z0-9]+/g,'_'),message:`Content ${item.code} must be reviewed and marked validated before market publication.`});}
 const evidenceRows=(await env.DB.prepare(`SELECT task_key,status,evidence_json FROM platform_market_launch_task_evidence WHERE package_version_id=?`).bind(Number(v.id)).all()).results||[];const evidenceByKey=new Map(evidenceRows.map(x=>[x.task_key,x]));
 const marketEvidence=evidenceByKey.get('market-status');if(!marketEvidence||marketEvidence.status!=='COMPLETE'||!assessMarketLaunchEvidence(parseJson(marketEvidence.evidence_json||'{}')).valid)blockers.push({code:'MARKET_STATUS_REVIEW_EVIDENCE_REQUIRED',message:'Record evidence that the market lifecycle status was inspected and resolved in the launch workbench.'});
 for(const item of pkg.legal.filter(x=>x.required)){const ev=evidenceByKey.get(`legal:${item.key}`);const e=ev?parseJson(ev.evidence_json||'{}'):{};if(item.status==='reviewed'&&(!ev||ev.status!=='COMPLETE'||!assessMarketLaunchEvidence(e).valid||!clean(e.reviewer,180)||!clean(e.decision,80)))blockers.push({code:'LEGAL_EVIDENCE_REQUIRED_'+item.key.toUpperCase(),message:`Legal item ${item.title} needs completed reviewer, decision and evidence records in the launch workbench.`});}
 for(const item of pkg.content){const ev=evidenceByKey.get(`content:${item.code}`);const e=ev?parseJson(ev.evidence_json||'{}'):{};if(['validated','active'].includes(String(item.status||'').toLowerCase())&&(!ev||ev.status!=='COMPLETE'||!assessMarketLaunchEvidence(e).valid))blockers.push({code:'CONTENT_EVIDENCE_REQUIRED_'+item.code.toUpperCase().replace(/[^A-Z0-9]+/g,'_'),message:`Content ${item.code} requires completed review evidence in the launch workbench.`});}
 for(const keyName of ['reconciliation','runtime-certification','mission-journey','publication-recovery']){const ev=evidenceByKey.get(keyName);const e=ev?parseJson(ev.evidence_json||'{}'):{};if(!ev||ev.status!=='COMPLETE'||!assessMarketLaunchEvidence(e).valid)blockers.push({code:'LAUNCH_EVIDENCE_REQUIRED_'+keyName.toUpperCase().replace(/[^A-Z0-9]+/g,'_'),message:`Complete ${keyName.replace(/-/g,' ')} with verifiable evidence in the launch workbench.`});}
 const readiness={valid:blockers.length===0,score:blockers.length?Math.max(0,Math.round(100-blockers.length*4)):100,blockers,warnings,canonicalTargets:canonical};
 await env.DB.prepare(`UPDATE platform_market_package_versions SET status=?,readiness_json=?,dependency_snapshot_json=?,updated_at=CURRENT_TIMESTAMP WHERE id=?`).bind(readiness.valid?'VALIDATED':'DRAFT',JSON.stringify(readiness),JSON.stringify(dependencies),Number(v.id)).run();
 await auditAdminControl(env,{actor,action:'admin.market-factory.validated',resourceType:'market_package_version',resourceId:v.id,requestId,metadata:{valid:readiness.valid,score:readiness.score,blockers:readiness.blockers.map(x=>x.code)}}).catch(error=>{throw authorityUnavailable('market_factory_audit',error);});return getMarketPackage(env,{packageId:Number(market.id)});
}

async function dependencySnapshotForPackage(env,pkg){
 const missing=[];for(const code of pkg.actions)if(!Object.values(ACTION_CODES).includes(code))missing.push({type:'action',code});
 for(const code of pkg.capabilities){const row=await env.DB.prepare(`SELECT code FROM canonical_capability_registry WHERE code=? LIMIT 1`).bind(code).first();if(!row)missing.push({type:'capability',code});}
 for(const p of pkg.providers){const row=await env.DB.prepare(`SELECT code,active FROM external_provider_registry WHERE code=? LIMIT 1`).bind(p.code).first();if(!row||Number(row.active)!==1)missing.push({type:'provider',code:p.code});}
 return {marketFactoryVersion:MARKET_FACTORY_VERSION,countryCode:pkg.country.iso,productKey:pkg.product.productKey||'on_mission',missing,timestamp:new Date().toISOString()};
}

export async function authorizeMarketPackage(env,actor,packageVersionId,requestId=''){
 const v=await env.DB.prepare(`SELECT * FROM platform_market_package_versions WHERE id=? LIMIT 1`).bind(Number(packageVersionId)).first();if(!v)throw fail('Market package version not found',404,'MARKET_PACKAGE_VERSION_NOT_FOUND');const r=parseJson(v.readiness_json);if(v.status!=='VALIDATED'||r.valid!==true)throw fail('Market package must be validated and ready before authorization.',409,'MARKET_PACKAGE_NOT_READY');const hash=await sha256Text(JSON.stringify({package:parseJson(v.package_json),dependencies:parseJson(v.dependency_snapshot_json),readiness:r}));const contract={contractVersion:'1.0',marketPackageVersionId:Number(v.id),packageKey:(await env.DB.prepare(`SELECT package_key FROM platform_market_packages WHERE id=?`).bind(Number(v.package_id)).first())?.package_key,country:parseJson(v.package_json).country,product:parseJson(v.package_json).product,regionalPlacement:parseJson(v.package_json).regionalPlacement||{regionKey:'',jurisdictionCode:'',policyVersion:'regional-placement-v1'},version:v.version,readiness:r,dependencies:parseJson(v.dependency_snapshot_json),createdAt:new Date().toISOString()};await env.DB.batch([env.DB.prepare(`UPDATE platform_market_package_versions SET status='AUTHORIZED',contract_hash=?,authorized_by_type=?,authorized_by_id=?,authorized_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE id=?`).bind(hash,actor.role,actor.id||null,Number(v.id)),env.DB.prepare(`INSERT INTO platform_market_release_contracts(package_version_id,contract_hash,contract_json,dependency_snapshot_json,status,authorized_by_type,authorized_by_id,authorized_at) VALUES(?,?,?,?, 'AUTHORIZED',?,?,CURRENT_TIMESTAMP) ON CONFLICT(package_version_id) DO UPDATE SET contract_hash=excluded.contract_hash,contract_json=excluded.contract_json,dependency_snapshot_json=excluded.dependency_snapshot_json,status='AUTHORIZED',authorized_by_type=excluded.authorized_by_type,authorized_by_id=excluded.authorized_by_id,authorized_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP`).bind(Number(v.id),hash,JSON.stringify(contract),JSON.stringify(contract.dependencies),actor.role,actor.id||null)]);await auditAdminControl(env,{actor,action:'admin.market-factory.authorized',resourceType:'market_package_version',resourceId:v.id,requestId,metadata:{contractHash:hash}}).catch(error=>{throw authorityUnavailable('market_factory_audit',error);});return getMarketPackage(env,{packageId:Number(v.package_id)});}

export async function publishMarketPackage(env,actor,packageVersionId,requestId='',{resume=false}={}){
 const v=await env.DB.prepare(`SELECT * FROM platform_market_package_versions WHERE id=? LIMIT 1`).bind(Number(packageVersionId)).first();if(!v)throw fail('Market package version not found',404,'MARKET_PACKAGE_VERSION_NOT_FOUND');
 const market=await env.DB.prepare(`SELECT * FROM platform_market_packages WHERE id=? LIMIT 1`).bind(Number(v.package_id)).first();if(['RETIRED','SUSPENDED','RESTRICTED'].includes(String(market?.status||'').toUpperCase()))throw fail(`Market status ${market.status} prevents publication; resolve the market lifecycle state first.`,409,'MARKET_STATUS_BLOCKS_PUBLICATION');const pkg=parseJson(v.package_json);const readiness=parseJson(v.readiness_json);if(readiness.valid!==true)throw fail('Market package is not ready for publication.',409,'MARKET_PACKAGE_NOT_READY');
 const prior=await env.DB.prepare(`SELECT * FROM platform_market_publication_operations WHERE package_version_id=? LIMIT 1`).bind(Number(v.id)).first();let opId,stage='PREPARED';if(prior){if(prior.status==='COMPLETED')return getMarketPackage(env,{packageId:Number(market.id)});if(!resume)throw fail(`Publication operation ${prior.id} is ${prior.status} at stage ${prior.stage}. Use the explicit recovery action to resume the idempotent reconciliation pipeline.`,409,'MARKET_PUBLICATION_RECOVERY_REQUIRED');if(!['RECOVERY_REQUIRED','IN_PROGRESS'].includes(prior.status)||!['AUTHORIZED','PUBLISHED'].includes(String(v.status)))throw fail('This publication operation is not eligible for safe recovery.',409,'MARKET_PUBLICATION_RECOVERY_NOT_ALLOWED');opId=Number(prior.id);stage='RECOVERY_REPLAY';await env.DB.prepare(`UPDATE platform_market_publication_operations SET status='IN_PROGRESS',stage=?,error_code=NULL,error_message=NULL,stage_evidence_json=?,updated_at=CURRENT_TIMESTAMP WHERE id=?`).bind(stage,JSON.stringify({recoveryBy:{type:actor.role,id:actor.id||null},recoveryAt:new Date().toISOString(),previousStage:prior.stage}),opId).run();}else{if(v.status!=='AUTHORIZED')throw fail('Market package must be authorized before publication.',409,'MARKET_PACKAGE_NOT_AUTHORIZED');const opKey=`market-publish:${Number(v.id)}:${crypto.randomUUID()}`;const opInsert=await env.DB.prepare(`INSERT INTO platform_market_publication_operations(package_version_id,package_id,operation_key,status,stage,started_by_type,started_by_id) VALUES(?,?,?,'IN_PROGRESS','PREPARED',?,?)`).bind(Number(v.id),Number(market.id),opKey,actor.role,actor.id||null).run();opId=Number(opInsert.meta?.last_row_id);}
 const setStage=async(next,evidence={})=>{stage=next;await env.DB.prepare(`UPDATE platform_market_publication_operations SET status='IN_PROGRESS',stage=?,stage_evidence_json=?,updated_at=CURRENT_TIMESTAMP WHERE id=?`).bind(next,JSON.stringify(evidence),opId).run();};
 try{
  await setStage('RECONCILING_CANONICAL');const canonical=await upsertCanonical(env,pkg,actor);
  await setStage('RECONCILING_GOVERNANCE',{canonicalCountry:canonical.country?.code||pkg.country.iso});const governanceEvidence=await reconcileRuntimeGovernance(env,pkg);
  await setStage('COMPOSING_LAUNCH');const composed=await ensureLaunchAndDefinitions(env,pkg,actor);
  await setStage('VALIDATING_LAUNCH',{launchId:Number(composed.launch.id)});const launch=await validateCountryProductLaunch(env,actor,Number(composed.launch.id),requestId);if(launch.status!=='validated')throw fail('Underlying country product launch did not validate.',409,'MARKET_LAUNCH_NOT_VALIDATED');
  await setStage('RETIRING_COMPETING_DRAFTS',{launchId:Number(composed.launch.id)});const retireStatements=[env.DB.prepare(`UPDATE country_product_launches SET status='retired',active=0,updated_at=CURRENT_TIMESTAMP WHERE country_code=? AND id<>? AND status='draft' AND active=0`).bind(pkg.country.iso,Number(composed.launch.id))];await env.DB.batch(retireStatements);
  await setStage('ACTIVATING_RELEASE');const previous=market.active_version_id?Number(market.active_version_id):null;const contract=await env.DB.prepare(`SELECT * FROM platform_market_release_contracts WHERE package_version_id=? LIMIT 1`).bind(Number(v.id)).first();if(!contract)throw fail('Market release contract is missing.',409,'MARKET_CONTRACT_MISSING');
  await env.DB.batch([env.DB.prepare(`UPDATE platform_market_package_versions SET launch_id=?,status='PUBLISHED',published_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE id=?`).bind(Number(composed.launch.id),Number(v.id)),env.DB.prepare(`UPDATE platform_market_release_contracts SET status='PUBLISHED',published_at=CURRENT_TIMESTAMP,verification_json='{}',updated_at=CURRENT_TIMESTAMP WHERE package_version_id=?`).bind(Number(v.id))]);
  await setStage('AUDITING_PUBLICATION',{launchId:Number(composed.launch.id),previousVersionId:previous,releaseStatus:'PUBLISHED',activationDeferred:true});await auditAdminControl(env,{actor,action:'admin.market-factory.published',resourceType:'market_package_version',resourceId:v.id,requestId,metadata:{packageId:market.id,previousVersionId:previous,countryCode:pkg.country.iso,releaseStatus:'PUBLISHED',activationDeferredUntilVerification:true,reconciledCanonical:{country:canonical.country?.code||pkg.country.iso,sectors:pkg.sectors.map(x=>x.code),policies:pkg.policies.map(x=>x.code),content:pkg.content.map(x=>x.code)},governance:governanceEvidence,publicationOperationId:opId}}).catch(error=>{throw authorityUnavailable('market_factory_audit',error);});
  await env.DB.prepare(`UPDATE platform_market_publication_operations SET status='COMPLETED',stage='PUBLISHED_WAITING_VERIFICATION',stage_evidence_json=?,completed_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE id=?`).bind(JSON.stringify({launchId:Number(composed.launch.id),releaseStatus:'PUBLISHED',marketActivated:false,onboardingMode:'CLOSED'}),opId).run();return getMarketPackage(env,{packageId:Number(market.id)});
 }catch(error){const code=error?.code||'MARKET_PUBLICATION_FAILED';const message=String(error?.message||'Publication failed. Inspect durable operation state before any recovery.').slice(0,2000);await env.DB.prepare(`UPDATE platform_market_publication_operations SET status='RECOVERY_REQUIRED',stage=?,error_code=?,error_message=?,stage_evidence_json=?,updated_at=CURRENT_TIMESTAMP WHERE id=?`).bind(stage,code,message,JSON.stringify({recoveryRequired:true,automaticRetryAllowed:false}),opId).run();throw fail(`Publication did not complete safely (operation ${opId}, stage ${stage}). ${message} Review the durable operation record; automatic retry is blocked.`,409,'MARKET_PUBLICATION_RECOVERY_REQUIRED');}
}

export async function recoverMarketPublication(env,actor,packageVersionId,requestId=''){return publishMarketPackage(env,actor,packageVersionId,requestId,{resume:true});}

export async function verifyMarketPackage(env,actor,packageVersionId,{summary='',evidenceRef=''}={},requestId=''){
 const v=await env.DB.prepare(`SELECT v.*,p.id package_id,p.status market_status,p.active_version_id FROM platform_market_package_versions v JOIN platform_market_packages p ON p.id=v.package_id WHERE v.id=? LIMIT 1`).bind(Number(packageVersionId)).first();if(!v)throw fail('Market package version not found',404,'MARKET_PACKAGE_VERSION_NOT_FOUND');if(v.status!=='PUBLISHED')throw fail('Only a PUBLISHED release can be verified.',409,'MARKET_RELEASE_NOT_PUBLISHED');if(clean(summary,2000).length<10||clean(evidenceRef,1000).length<3)throw fail('Verification requires a meaningful summary and an evidence reference.',422,'MARKET_VERIFICATION_EVIDENCE_REQUIRED');
 const wb=await getMarketLaunchWorkbench(env,Number(v.id));const required=['runtime-certification','mission-journey','publication-recovery'];const incomplete=required.filter(k=>!wb.tasks.some(t=>t.key===k&&t.status==='COMPLETE'&&t.evidence?.evidenceRef));if(incomplete.length)throw fail(`Verification blocked; missing evidence tasks: ${incomplete.join(', ')}.`,409,'MARKET_VERIFICATION_EVIDENCE_INCOMPLETE');
 const operation=await env.DB.prepare(`SELECT status,stage FROM platform_market_publication_operations WHERE package_version_id=? LIMIT 1`).bind(Number(v.id)).first();if(!operation||operation.status!=='COMPLETED'||operation.stage!=='PUBLISHED_WAITING_VERIFICATION')throw fail('Publication operation is not in a clean published state; inspect and resolve operation recovery before verification.',409,'MARKET_PUBLICATION_RECOVERY_REQUIRED');const launch=await env.DB.prepare(`SELECT id,status,active FROM country_product_launches WHERE id=? LIMIT 1`).bind(Number(v.launch_id)).first();if(!launch||String(launch.status).toLowerCase()!=='validated')throw fail('Underlying country product launch is not in validated state.',409,'MARKET_LAUNCH_NOT_VALIDATED');
 const verification={summary:clean(summary,2000),evidenceRef:clean(evidenceRef,1000),verifiedBy:{type:actor.role,id:actor.id||null},verifiedAt:new Date().toISOString(),launchId:Number(v.launch_id),checks:{launchValidated:true,requiredWorkbenchEvidenceComplete:true,marketActivated:false}};
 await env.DB.batch([env.DB.prepare(`UPDATE platform_market_package_versions SET status='VERIFIED',verified_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE id=? AND status='PUBLISHED'`).bind(Number(v.id)),env.DB.prepare(`UPDATE platform_market_release_contracts SET status='VERIFIED',verification_json=?,verified_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE package_version_id=? AND status='PUBLISHED'`).bind(JSON.stringify(verification),Number(v.id)),env.DB.prepare(`UPDATE platform_market_publication_operations SET stage='VERIFIED_WAITING_ACTIVATION',stage_evidence_json=?,updated_at=CURRENT_TIMESTAMP WHERE package_version_id=? AND status='COMPLETED'`).bind(JSON.stringify({verificationEvidence:verification.evidenceRef,marketActivated:false}),Number(v.id))]);await auditAdminControl(env,{actor,action:'admin.market-factory.verified',resourceType:'market_package_version',resourceId:v.id,requestId,metadata:{evidenceRef:verification.evidenceRef,launchId:Number(v.launch_id),activationDeferred:true}}).catch(error=>{throw authorityUnavailable('market_factory_audit',error);});return getMarketPackage(env,{packageId:Number(v.package_id)});
}
export async function activateVerifiedMarketPackage(env,actor,packageVersionId,requestId=''){
 const v=await env.DB.prepare(`SELECT v.*,p.id package_id,p.status market_status,p.active_version_id FROM platform_market_package_versions v JOIN platform_market_packages p ON p.id=v.package_id WHERE v.id=? LIMIT 1`).bind(Number(packageVersionId)).first();if(!v)throw fail('Market package version not found',404,'MARKET_PACKAGE_VERSION_NOT_FOUND');if(v.status!=='VERIFIED')throw fail('Release must be VERIFIED before market activation.',409,'MARKET_RELEASE_NOT_VERIFIED');if(['SUSPENDED','RETIRED','RESTRICTED'].includes(String(v.market_status||'').toUpperCase()))throw fail(`Market status ${v.market_status} blocks activation; explicitly resolve the market lifecycle state first.`,409,'MARKET_STATUS_BLOCKS_ACTIVATION');const operation=await env.DB.prepare(`SELECT status,stage FROM platform_market_publication_operations WHERE package_version_id=? LIMIT 1`).bind(Number(v.id)).first();if(!operation||operation.status!=='COMPLETED'||!['PUBLISHED_WAITING_VERIFICATION','VERIFIED_WAITING_ACTIVATION','LIVE'].includes(operation.stage))throw fail('Publication operation must be reconciled before activation.',409,'MARKET_PUBLICATION_RECOVERY_REQUIRED');const contract=await env.DB.prepare(`SELECT status,verification_json FROM platform_market_release_contracts WHERE package_version_id=? LIMIT 1`).bind(Number(v.id)).first();if(contract?.status!=='VERIFIED'||!parseJson(contract.verification_json||'{}').evidenceRef)throw fail('Verified release contract evidence is missing.',409,'MARKET_VERIFICATION_CONTRACT_MISSING');
 const previous=v.active_version_id?Number(v.active_version_id):null;const statements=[];if(previous&&previous!==Number(v.id)){statements.push(env.DB.prepare(`UPDATE platform_market_package_versions SET status='REPLACED',updated_at=CURRENT_TIMESTAMP WHERE id=? AND status IN ('LIVE','VERIFIED','PUBLISHED','AUTHORIZED')`).bind(previous));statements.push(env.DB.prepare(`UPDATE platform_market_release_contracts SET status='REPLACED',updated_at=CURRENT_TIMESTAMP WHERE package_version_id=? AND status IN ('LIVE','VERIFIED','PUBLISHED','AUTHORIZED')`).bind(previous));}statements.push(env.DB.prepare(`UPDATE platform_market_package_versions SET status='LIVE',live_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE id=? AND status='VERIFIED'`).bind(Number(v.id)));statements.push(env.DB.prepare(`UPDATE platform_market_release_contracts SET status='LIVE',live_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE package_version_id=? AND status='VERIFIED'`).bind(Number(v.id)));statements.push(env.DB.prepare(`UPDATE platform_market_packages SET status='LIVE',onboarding_mode='INVITE_ONLY',previous_version_id=?,active_version_id=?,updated_at=CURRENT_TIMESTAMP WHERE id=?`).bind(previous,Number(v.id),Number(v.package_id)));await env.DB.batch(statements);await env.DB.prepare(`UPDATE platform_market_publication_operations SET status='COMPLETED',stage='LIVE',stage_evidence_json=?,completed_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE package_version_id=?`).bind(JSON.stringify({marketActivated:true,onboardingMode:'INVITE_ONLY',activeVersionId:Number(v.id)}),Number(v.id)).run();await auditAdminControl(env,{actor,action:'admin.market-factory.activated',resourceType:'market_package_version',resourceId:v.id,requestId,metadata:{packageId:Number(v.package_id),previousVersionId:previous,onboardingMode:'INVITE_ONLY',verificationEvidence:true}}).catch(error=>{throw authorityUnavailable('market_factory_audit',error);});return getMarketPackage(env,{packageId:Number(v.package_id)});
}

export async function setMarketStatus(env,actor,packageId,status,{onboardingMode=null,requestId=''}={}){const allowed=['LIVE','RESTRICTED','SUSPENDED','RETIRED','DRAFT'];if(!allowed.includes(status))throw fail('Invalid market status',422,'MARKET_STATUS_INVALID');const m=await env.DB.prepare(`SELECT * FROM platform_market_packages WHERE id=? LIMIT 1`).bind(Number(packageId)).first();if(!m)throw fail('Market package not found',404,'MARKET_PACKAGE_NOT_FOUND');if(status==='DRAFT'&&m.active_version_id)throw fail('A market with a published release cannot be changed back to DRAFT. Suspend, restrict or retire it instead.',409,'MARKET_STATUS_TRANSITION_INVALID');if(status==='LIVE'&&String(m.status).toUpperCase()==='RETIRED')throw fail('A retired market cannot be resumed directly. Create or select a release and pass the explicit verification/activation workflow.',409,'MARKET_STATUS_TRANSITION_INVALID');if(status==='LIVE'&&!m.active_version_id)throw fail('A market cannot be set LIVE without an active release that has passed PUBLISHED → VERIFIED → LIVE.',409,'MARKET_RELEASE_ACTIVATION_REQUIRED');const mode=onboardingMode&&['OPEN','INVITE_ONLY','CLOSED'].includes(onboardingMode)?onboardingMode:(status==='LIVE'?'INVITE_ONLY':'CLOSED');await env.DB.prepare(`UPDATE platform_market_packages SET status=?,onboarding_mode=?,updated_at=CURRENT_TIMESTAMP WHERE id=?`).bind(status,mode,Number(packageId)).run();if(m.active_version_id){if(status==='SUSPENDED'||status==='RETIRED'){const versionStatus=status;await env.DB.prepare(`UPDATE platform_market_package_versions SET status=?,updated_at=CURRENT_TIMESTAMP WHERE id=?`).bind(versionStatus,Number(m.active_version_id)).run();await env.DB.prepare(`UPDATE platform_market_release_contracts SET status=?,updated_at=CURRENT_TIMESTAMP WHERE package_version_id=?`).bind(versionStatus,Number(m.active_version_id)).run();}else if(status==='LIVE'){await env.DB.prepare(`UPDATE platform_market_package_versions SET status='LIVE',updated_at=CURRENT_TIMESTAMP WHERE id=?`).bind(Number(m.active_version_id)).run();await env.DB.prepare(`UPDATE platform_market_release_contracts SET status='LIVE',updated_at=CURRENT_TIMESTAMP WHERE package_version_id=?`).bind(Number(m.active_version_id)).run();}}await auditAdminControl(env,{actor,action:`admin.market-factory.status.${status.toLowerCase()}`,resourceType:'market_package',resourceId:packageId,requestId,metadata:{status,onboardingMode:mode}}).catch(error=>{throw authorityUnavailable('market_factory_audit',error);});return getMarketPackage(env,{packageId:Number(packageId)});}

export async function exportMarketPackage(env,{packageId=null,versionId=null}={}){let v;if(versionId)v=await env.DB.prepare(`SELECT * FROM platform_market_package_versions WHERE id=? LIMIT 1`).bind(Number(versionId)).first();else if(packageId){const m=await env.DB.prepare(`SELECT active_version_id FROM platform_market_packages WHERE id=?`).bind(Number(packageId)).first();v=m?.active_version_id?await env.DB.prepare(`SELECT * FROM platform_market_package_versions WHERE id=?`).bind(Number(m.active_version_id)).first():await env.DB.prepare(`SELECT * FROM platform_market_package_versions WHERE package_id=? ORDER BY id DESC LIMIT 1`).bind(Number(packageId)).first();}if(!v)throw fail('No market package version available for export.',404,'MARKET_PACKAGE_EXPORT_NOT_FOUND');const pkg=parseJson(v.package_json);return {filename:`${pkg.country.iso}-market-package-${v.version}.json`,schemaVersion:'1.0',packageType:'market-package',package:pkg,source:{versionId:Number(v.id),status:v.status,contractHash:v.contract_hash||null,exportedAt:new Date().toISOString()}};}

